// Node.js writable stream backpressure example
const fs = require('fs');
const out = fs.createWriteStream('bigfile.out');
async function produce() {
  for (let i = 0; i < 1e6; i++) {
    const ok = out.write('chunk ' + i + '\n');
    if (!ok) {
      await new Promise(resolve => out.once('drain', resolve));
    }
  }
  out.end();
}
produce();
